def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

results = []
for k in range(1, 10001):
    if count_divisors(2 * (k**3)) == 2 * k:
        results.append(k)

print(results)
